module tree_avg_dist (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [63:0] dist_matrix,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] CALC_SUM = 3'd1;\n    localparam [2:0] DIVIDE   = 3'd2;\n    localparam [2:0] CONVERT  = 3'd3;\n    localparam [2:0] DONE_ST  = 3'd4;\n\n    reg [2:0] state;\n    reg [3:0] i;\n    reg [3:0] j;\n    reg [7:0] dist_sum;\n    reg [7:0] divisor;\n    reg [15:0] temp_result;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state     <= IDLE;\n            result    <= 16'd0;\n            done      <= 1'b0;\n            dist_sum  <= 8'd0;\n            divisor   <= 8'd0;\n            temp_result <= 16'd0;\n            i         <= 4'd0;\n            j         <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= CALC_SUM;\n                        dist_sum <= 8'd0;\n                        i <= 4'd0;\n                        j <= 4'd0;\n                    end\n                end\n                \n                CALC_SUM: begin\n                    if (i < n && j < n) begin\n                        if (i < j) begin\n                            // Access 1-bit from packed matrix at (i,j)\n                            dist_sum <= dist_sum + dist_matrix[i*8 + j];\n                        end\n                        if (j == n-1) begin\n                            j <= 4'd0;\n                            i <= i + 4'd1;\n                        end else begin\n                            j <= j + 4'd1;\n                        end\n                    end else begin\n                        // Calculate divisor = n*(n-1)/2\n                        divisor <= (n * (n - 4'd1)) >> 1;\n                        state <= DIVIDE;\n                    end\n                end\n                \n                DIVIDE: begin\n                    if (divisor != 8'd0) begin\n                        temp_result <= (dist_sum << 8) / divisor;\n                    end else begin\n                        temp_result <= 16'd0;\n                    end\n                    state <= CONVERT;\n                end\n                \n                CONVERT: begin\n                    result <= temp_result;\n                    state <= DONE_ST;\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule